import json
from pathlib import Path

ROOT = Path.cwd()
packet = json.loads((ROOT / 'artifacts/answer_repair/review_20261013/review_packet.json').read_text())
records = {r['review_id']: r for r in packet['records']}
notes = []

def add(key, decision, label, answer_status, evidence_status, confidence, reason, question, quotes, flags=()):
    ds, sid = key.split(':', 1)
    for rank, text in quotes:
        assert text in records[key]['evidence'][rank-1]['text'], (key, rank, text)
    notes.append(dict(dataset=ds, sample_id=sid, reviewer_type='agent', reviewer='Codex',
                      review_date='2026-10-13', human_verified=False,
                      evidence_basis='Archived C1 Top-5 only; selected passages and contrasts cited below; no external fact lookup or oracle evidence used',
                      e_core_suggestion=decision, suggested_label=label,
                      initial_answer_status=answer_status, evidence_status=evidence_status,
                      confidence=confidence, reason_zh=reason, human_question_zh=question,
                      flags=list(flags), quoted_evidence=[dict(rank=rank, quote=text) for rank,text in quotes]))

def core(key, reason, question, quotes, confidence='high', flags=()):
    add(key,'include_candidate','evidence_utilisation','incorrect','sufficient_clear',confidence,reason,question,quotes,flags)

def control(key, reason, question, quotes, confidence='high', flags=()):
    add(key,'retain_control_candidate','correct','correct','sufficient_clear',confidence,reason,question,quotes,flags)

